function getState(){try{return JSON.parse(localStorage.getItem('alpendre-demo-state'))||{doneTasks:[],extra:{}}}catch{return{doneTasks:[],extra:{}}}}
let state=getState();let current='overview';let globalFilter='';let toastTimer;const root=document.getElementById('app');
function setState(){try{localStorage.setItem('alpendre-demo-state',JSON.stringify(state))}catch{}}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function moduleBy(id){return sampleModules.find(m=>m.id===id)}
function titleFor(id){return id==='overview'?'Visão geral':moduleBy(id)?.label||id}
function listItems(id){const base=demoRecords.find(x=>x.id===id)?.items||[];return[...base,...(state.extra[id]||[])]}
function go(id){current=id;globalFilter='';render()}
function landing(){return `<main class="landing"><nav class="site-nav"><a class="brand" href="#inicio"><img class="brand-art" src="/assets/alpendre-logo.png" alt="Alpendre Gestão" /></a><div class="nav-links"><a href="#recursos">Recursos</a><a href="#modulos">Módulos</a><a href="#white-label">White label</a></div><div class="nav-actions"><button class="btn btn-quiet" data-action="demo">Acessar demonstração</button><button class="btn btn-primary" data-action="demo">Explorar o painel <span class="arrow">↗</span></button></div></nav><section class="hero"><div class="hero-copy"><span class="hero-kicker"><i></i> GESTÃO FEITA PARA QUEM PROJETA</span><h1>Seu escritório em ordem. <em>Sua arquitetura, em movimento.</em></h1><p>Do primeiro contato ao pós-obra: projetos, clientes, prazos, documentos e financeiro reunidos em um lugar que acompanha o seu jeito de trabalhar.</p><div class="hero-cta"><button class="btn btn-primary" data-action="demo">Conheça a plataforma <span class="arrow">↗</span></button><a class="btn btn-quiet" href="#recursos">Ver o que dá para organizar <span>↓</span></a></div><div class="micro-proof"><div class="avatar-stack"><i>H</i><i>L</i><i>C</i><i>R</i></div><span>Uma visão completa da operação,<br>com espaço para cada detalhe.</span></div></div><div class="hero-art"><div class="art-halo"></div><div class="float-note">+ 12,8%<small>projetos no prazo</small></div><article class="art-card"><div class="art-top"><strong>ALPENDRE · VISÃO DO ESCRITÓRIO</strong><span>Novembro 2026</span></div><div class="art-salute"><div class="art-avatar">HN</div><div><small>Bom dia, Helena</small><b>Seu espaço está em movimento.</b></div></div><div class="art-stats"><div class="mini-stat"><span>Projetos ativos</span><b>12</b></div><div class="mini-stat"><span>Em andamento</span><b>08</b></div><div class="mini-stat"><span>Receita prevista</span><b>R$ 42k</b></div></div><div class="art-chart"><label>Ritmo dos projetos</label><svg viewBox="0 0 360 90" preserveAspectRatio="none"><path d="M0 76 C34 71 38 53 74 58S120 66 149 44 194 48 219 31 268 44 290 23 333 23 360 8" fill="none" stroke="#eb5576" stroke-width="3" stroke-linecap="round"/><path d="M0 76 C34 71 38 53 74 58S120 66 149 44 194 48 219 31 268 44 290 23 333 23 360 8V90H0Z" fill="#eb5576" opacity=".09"/></svg></div><div class="art-bottom"><div class="art-project"><span class="project-thumb"></span><span><b>Casa Paineira</b><br>Anteprojeto · 68%</span></div><span>Entrega em 7 dias</span></div></article><div class="float-pulse"><b>✓</b> Aprovação recebida <small>Vila das Águas · há 12 min</small></div></div></section><section class="section" id="recursos"><div class="section-head"><span class="eyebrow">Mais clareza em cada etapa</span><h2>Um lugar para o trabalho acontecer por inteiro.</h2><p>Menos informação espalhada. Mais visão de ponta a ponta para tomar decisões e conduzir cada projeto com segurança.</p></div><div class="feature-grid"><article class="feature-card"><div class="feature-icon">${icon('project')}</div><h3>Projetos que avançam</h3><p>Fases, entregáveis, responsáveis, horas e marcos em uma visão que mostra o que vem pela frente.</p></article><article class="feature-card"><div class="feature-icon">${icon('client')}</div><h3>Relacionamentos bem cuidados</h3><p>Histórico de cada conversa, briefing, proposta, aprovação e combinação com o cliente.</p></article><article class="feature-card"><div class="feature-icon">${icon('chart')}</div><h3>Gestão com contexto</h3><p>Agenda, financeiro, obra e equipe conectados ao projeto que precisa da sua atenção.</p></article></div></section><section class="section" id="modulos"><div class="section-head"><span class="eyebrow">A operação completa</span><h2>Da primeira conversa ao cuidado depois da entrega.</h2><p>Módulos que se conectam em uma operação única, com espaço para crescer junto com o escritório.</p></div><div class="module-strip">${['CRM e oportunidades','Propostas e contratos','Clientes e imóveis','Briefing e levantamentos','Projetos e fases','Agenda e tarefas','Documentos e versões','Aprovações','RRT e licenças','Financeiro','Obras','Fornecedores','Riscos e qualidade','Entregas e pós-obra','Equipe e permissões','Automações','Relatórios','White label'].map(x=>`<span class="module-chip"><b>↗</b>${x}</span>`).join('')}</div></section><section class="cta-band" id="white-label"><div><h2>Uma experiência com a identidade do seu escritório.</h2><p>Marca, domínio, portal do cliente e preferências em uma estrutura white label.</p></div><button class="btn" data-action="demo">Explorar a demonstração <span>↗</span></button></section><footer class="site-footer"><span>© 2026 Alpendre Gestão · Feito para quem projeta com intenção.</span><span>Desenvolvido por LMX Soluções Digitais/Segundo Almeida</span></footer></main>`}
function appShell(){return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="side-brand"><img class="brand-art" src="/assets/alpendre-logo.png" alt="Alpendre Gestão" /></div><div class="workspace-switch"><span class="workspace-emblem">EA</span><span><b>Estúdio Alpendre</b><small>Espaço demonstrativo</small></span><span class="workspace-chevron">⌄</span></div><nav class="side-nav">${sectionGroups.map(([group,links])=>`<div class="nav-caption">${group}</div>${links.map(([id,label,ic])=>`<button class="side-link ${current===id?'active':''}" data-nav="${id}">${icon(ic)}<span>${label}</span>${id==='aprovacoes'?'<i class="nav-badge">3</i>':''}</button>`).join('')}`).join('')}</nav><div class="side-bottom"><div class="plan-mini"><header><b>Plano Essencial</b><span>Demo</span></header><div class="plan-meter"><i></i></div><small>4 de 6 assentos utilizados</small></div><div class="side-user"><span class="user-pic">HN</span><span><b>Helena Nogueira</b><small>Administradora</small></span><button title="Minha conta" data-nav="equipe">···</button></div></div></aside><button class="mobile-overlay" aria-label="Fechar menu" data-action="close-menu"></button><div class="main-column"><header class="topbar"><button class="mobile-menu" aria-label="Abrir menu" data-action="menu">${icon('menu')}</button><div class="crumb">Alpendre Gestão <span> / </span> <b>${escapeHtml(titleFor(current))}</b></div><label class="top-search">${icon('search')}<input id="global-search" placeholder="Buscar em tudo" value="${escapeHtml(globalFilter)}" /></label><button class="icon-btn" title="Notificações" data-action="notifications">${icon('bell')}<i class="notif-dot"></i></button><button class="icon-btn" title="Preferências" data-nav="marca">${icon('settings')}</button><span class="top-avatar">HN</span></header><main class="content">${current==='overview'?overview():moduleView(current)}</main><footer class="app-footer"><span>© 2026 Alpendre Gestão · Espaço demonstrativo</span><b>Desenvolvido por LMX Soluções Digitais/Segundo Almeida</b></footer></div><div id="overlay-root"></div><div class="toast-wrap" id="toast-wrap"></div></div>`}
function metric(label,value,meta,ic,trend='up'){return `<article class="metric-card"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon">${icon(ic)}</span></div><div class="metric-value">${value}</div><div class="metric-meta"><span class="trend-${trend}">${meta.split('|')[0]}</span> ${meta.split('|')[1]||''}</div><svg class="metric-spark" viewBox="0 0 70 28"><path d="M0 22 C12 18 15 23 25 14S41 20 51 8 61 12 70 3" fill="none" stroke="${trend==='up'?'#438b71':'#eb5576'}" stroke-width="2"/></svg></article>`}
function chartSvg(){return `<svg class="overview-chart" viewBox="0 0 620 190" preserveAspectRatio="none"><defs><linearGradient id="areaGrad" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#eb5576" stop-opacity=".18"/><stop offset="1" stop-color="#eb5576" stop-opacity="0"/></linearGradient></defs><line class="chart-grid-line" x1="44" y1="35" x2="610" y2="35"/><line class="chart-grid-line" x1="44" y1="75" x2="610" y2="75"/><line class="chart-grid-line" x1="44" y1="115" x2="610" y2="115"/><line class="chart-grid-line" x1="44" y1="155" x2="610" y2="155"/><text class="chart-label" x="4" y="38">40k</text><text class="chart-label" x="4" y="78">30k</text><text class="chart-label" x="4" y="118">20k</text><text class="chart-label" x="4" y="158">10k</text><path class="chart-area" d="M44 142 C82 132 91 111 135 119 S178 144 225 101 267 108 310 89 365 106 405 65 456 81 492 49 548 66 610 25 V160 H44Z"/><path class="chart-line" d="M44 142 C82 132 91 111 135 119 S178 144 225 101 267 108 310 89 365 106 405 65 456 81 492 49 548 66 610 25"/><path class="chart-line secondary" d="M44 153 C88 145 105 132 135 139 S189 120 225 128 271 112 310 121 366 96 405 103 451 95 492 89 555 72 610 74"/><circle class="chart-dot" cx="492" cy="49" r="4"/><text class="chart-label" x="44" y="181">Jun</text><text class="chart-label" x="137" y="181">Jul</text><text class="chart-label" x="230" y="181">Ago</text><text class="chart-label" x="323" y="181">Set</text><text class="chart-label" x="416" y="181">Out</text><text class="chart-label" x="510" y="181">Nov</text><text class="chart-label" x="583" y="181">Dez</text></svg>`}
function overview(){const tasks=[['Validar detalhamento de marcenaria','Vila das Águas · Lívia Carvalho','Hoje',false],['Enviar revisão do memorial','Clínica Horizonte · Helena','Amanhã',false],['Conferir medições da obra','Casa Ipê Roxo · Caio','22 nov',true],['Retorno da proposta comercial','Casa Paineira · Helena','23 nov',false]];return `<section class="page-head"><div><h1>Bom dia, Helena <span style="font-size:21px">☀</span></h1><p>Uma visão clara do que está acontecendo no seu escritório.</p></div><div class="head-actions"><span class="demo-pill"><i></i> Ambiente com dados fictícios</span><span class="api-status" id="api-status">Banco de dados · verificando</span><button class="btn btn-primary btn-small" data-action="quick-create">${icon('plus')} Novo registro</button></div></section><section class="welcome-panel"><div class="welcome-copy"><span>SÁBADO, 21 DE NOVEMBRO DE 2026</span><h2>Seu trabalho está tomando forma.</h2><p>Hoje há <strong>4 tarefas</strong> pedindo atenção e <strong>2 visitas</strong> nesta semana.</p></div><div class="welcome-extra"><div class="welcome-stat"><small>Projetos no ritmo</small><b>83%</b></div><span class="welcome-doodle">↗</span></div></section><section class="metric-grid">${metric('Projetos ativos','12','+2,4%| no mês','project')}${metric('Oportunidades abertas','08','+18%| no trimestre','crm')}${metric('A receber no mês','R$ 42,8 mil','+8,2%| vs. mês anterior','finance')}${metric('Tarefas em dia','94%','+5,1%| nesta semana','check')}</section><section class="panel-grid"><article class="panel"><header class="panel-title"><div><h3>Ritmo do escritório</h3><p>Receita contratada e entregas previstas</p></div><div class="chart-legend"><span><i style="background:#eb5576"></i>Receita</span><span><i style="background:#8c7096"></i>Entregas</span></div></header>${chartSvg()}</article><article class="panel"><header class="panel-title"><div><h3>Projetos em destaque</h3><p>Onde o time está colocando energia</p></div><button class="link-button" data-nav="projetos">Ver todos</button></header><div class="project-list">${[['Casa Paineira','Anteprojeto · Helena',68],['Clínica Horizonte','Estudo preliminar · Lívia',42],['Vila das Águas','Detalhamento · Caio',81],['Casa Ipê Roxo','Compatibilização · Helena',93]].map((p,i)=>`<div class="project-row"><span class="project-cover"></span><span class="project-info"><strong>${p[0]}</strong><small>${p[1]}</small><span class="progress"><i style="width:${p[2]}%"></i></span></span><b class="project-percent">${p[2]}%</b></div>`).join('')}</div></article></section><section class="lower-grid"><article class="panel"><header class="panel-title"><div><h3>Próximos passos</h3><p>O que precisa avançar</p></div><button class="link-button" data-nav="agenda">Abrir agenda</button></header><div class="task-list">${tasks.map((t,i)=>{const done=state.doneTasks.includes(i);return `<div class="task-row"><button class="task-check ${done?'done':''}" data-task="${i}" aria-label="Marcar tarefa">${done?icon('check'):''}</button><span class="task-copy"><strong style="${done?'text-decoration:line-through;color:#a59ca8':''}">${t[0]}</strong><small>${t[1]}</small></span><span class="due-tag" style="${t[2]==='Hoje'?'':'color:#928895;background:#f2eff3'}">${done?'Concluída':t[2]}</span></div>`}).join('')}</div></article><article class="panel"><header class="panel-title"><div><h3>Agenda desta semana</h3><p>21 a 27 de novembro</p></div><button class="link-button" data-nav="agenda">Calendário</button></header><div class="agenda-card"><time class="agenda-time">14:00</time><div class="agenda-event"><strong>Compatibilização · Casa Paineira</strong><small>Hoje · Equipe técnica</small></div></div><div class="agenda-card"><time class="agenda-time">09:30</time><div class="agenda-event"><strong>Visita · Clínica Horizonte</strong><small>Amanhã · Helena e cliente</small></div></div><div class="agenda-card"><time class="agenda-time">16:00</time><div class="agenda-event"><strong>Apresentação · Vila das Águas</strong><small>Quinta · Reunião com cliente</small></div></div><div class="agenda-card"><time class="agenda-time">11:00</time><div class="agenda-event"><strong>Revisão de propostas</strong><small>Sexta · Reunião interna</small></div></div></article><article class="panel"><header class="panel-title"><div><h3>Atividade recente</h3><p>O que mudou há pouco</p></div><button class="link-button" data-nav="relatorios">Histórico</button></header><div class="activity-list"><div class="activity-row"><i class="activity-dot"></i><div class="activity-copy"><b>Marina Albuquerque</b> aprovou a paleta de materiais.<small>Vila das Águas · há 12 min</small></div></div><div class="activity-row"><i class="activity-dot"></i><div class="activity-copy"><b>Lívia Carvalho</b> publicou uma nova versão da planta.<small>Casa Paineira · há 46 min</small></div></div><div class="activity-row"><i class="activity-dot"></i><div class="activity-copy"><b>Helena Nogueira</b> registrou visita técnica.<small>Casa Ipê Roxo · ontem</small></div></div><div class="activity-row"><i class="activity-dot"></i><div class="activity-copy"><b>Alpendre Gestão</b> enviou um lembrete de aprovação.<small>Clínica Horizonte · ontem</small></div></div></div></article></section><div class="demo-note">Os nomes, valores, projetos, indicadores e atividades exibidos são fictícios e servem apenas para demonstração da plataforma.</div>`}
function statusClass(s=''){const t=s.toLowerCase();if(/pend|aguard|risco|análise|atenção|revisão/.test(t))return'warn';if(/novo|atras|bloque|aprovar/.test(t))return'pink';if(/conclu|emitida|ativo|entregue|aprovad|ritmo|resolvida|organizado|configurado|programad/.test(t))return'';return'neutral'}
function moduleView(id){const mod=moduleBy(id);if(!mod)return overview();if(id==='marca')return settingsView(mod);if(id==='plataforma')return platformView(mod);if(id==='projetos')return projectView(mod);const allRows=listItems(id);const rows=allRows.filter(x=>`${x.name} ${x.subtitle} ${x.description} ${x.status}`.toLowerCase().includes(globalFilter.toLowerCase()));return `<section class="page-head"><div><h1>${escapeHtml(mod.label)}</h1><p>${escapeHtml(mod.description)}</p></div><div class="head-actions"><span class="demo-pill"><i></i> Dados demonstrativos</span><button class="btn btn-primary btn-small" data-create="${id}">${icon('plus')} Novo ${id==='crm'?'lead':'registro'}</button></div></section><div class="module-toolbar"><input class="filter-input" id="module-filter" placeholder="Buscar neste módulo" value="${escapeHtml(globalFilter)}"/>${id==='crm'?'<button class="filter-chip" data-action="filter">Todas as etapas ⌄</button><button class="filter-chip" data-action="filter">Origem: Todas ⌄</button>':''}${id==='financeiro'?'<button class="filter-chip" data-action="filter">Todos os períodos ⌄</button><button class="filter-chip" data-action="filter">Entradas e saídas ⌄</button>':''}<button class="filter-chip" data-action="export" data-module="${id}">↧ Exportar</button><span class="muted" style="font-size:10px;margin-left:auto">${rows.length} registros</span></div><section class="workspace-grid">${rows.map(row=>workspaceCard(row,mod,allRows.findIndex(item=>item.id===row.id))).join('')||`<div class="empty-state"><span>${icon(mod.icon)}</span><strong>Nenhum registro encontrado</strong><p>Tente buscar por outro termo ou crie um novo registro.</p></div>`}</section><div class="demo-note">${escapeHtml(mod.description)} · Dados fictícios preparados para apresentar o fluxo completo do módulo.</div>`}
function workspaceCard(row,mod,index){const valueLabel=['crm','propostas','financeiro'].includes(mod.id)?'Valor demonstrativo':mod.id==='projetos'||mod.id==='obras'?'Progresso':mod.id==='agenda'?'Duração':mod.id==='clientes'?'Relacionamento':'Referência';return `<article class="workspace-card" data-detail="${mod.id}" data-row="${index}"><header class="workspace-card-head"><div class="workspace-icon">${icon(mod.icon)}</div><span class="status ${statusClass(row.status)}">${escapeHtml(row.status)}</span></header><h3 style="margin-top:13px">${escapeHtml(row.name)}</h3><p>${escapeHtml(row.subtitle)}<br>${escapeHtml(row.description)}</p><footer class="card-meta"><span>${escapeHtml(valueLabel)} <b>${escapeHtml(row.value)}</b></span><span>Detalhes ↗</span></footer></article>`}
function projectView(mod){const data=listItems('projetos');const cols=[['A iniciar',[]],['Estudo e concepção',[]],['Desenvolvimento',[]],['Conclusão',[]]];data.forEach((p,i)=>cols[Math.min(3,Math.floor(i*4/data.length))][1].push({...p,progress:[68,42,81,93,100][i]||20}));return `<section class="page-head"><div><h1>Projetos e fases</h1><p>Uma visão compartilhada de prazos, entregas e responsáveis.</p></div><div class="head-actions"><span class="demo-pill"><i></i> Dados demonstrativos</span><button class="btn btn-primary btn-small" data-create="projetos">${icon('plus')} Novo projeto</button></div></section><div class="module-toolbar"><button class="filter-chip" data-action="switch-view">▦ Quadro</button><button class="filter-chip" data-action="switch-view">☷ Lista</button><button class="filter-chip" data-action="filter">Responsável: Todos ⌄</button><button class="filter-chip" data-action="filter">Etapa: Todas ⌄</button><span class="muted" style="margin-left:auto;font-size:10px">5 projetos no portfólio demonstrativo</span></div><section class="kanban">${cols.map(([name,items])=>`<div class="kanban-col"><header>${name}<span>${items.length.toString().padStart(2,'0')}</span></header>${items.map(item=>`<article class="kanban-item" data-detail="projetos" data-row="${data.findIndex(original=>original.id===item.id)}"><b>${escapeHtml(item.name)}</b><small>${escapeHtml(item.subtitle)} · ${escapeHtml(item.description)}</small><span class="progress"><i style="width:${item.progress}%"></i></span><em>${item.progress}% concluído</em></article>`).join('')}</div>`).join('')}</section><div class="demo-note">Fases, equipes e percentuais são fictícios. A estrutura prevê filtros, responsáveis, marcos e histórico por projeto.</div>`}
function settingsView(mod){return `<section class="page-head"><div><h1>Marca e ambiente white label</h1><p>Configure como cada escritório apresenta e usa a própria plataforma.</p></div><div class="head-actions"><span class="demo-pill"><i></i> Prévia demonstrativa</span><button class="btn btn-primary btn-small" data-action="save-settings">Salvar preferências</button></div></section><div class="settings-layout"><nav class="settings-nav"><button class="active" data-action="settings-tab">Identidade visual</button><button data-action="settings-tab">Domínio e acesso</button><button data-action="settings-tab">Portal do cliente</button><button data-action="settings-tab">Comunicação</button><button data-action="settings-tab">Privacidade e segurança</button><button data-action="settings-tab">Plano e consumo</button></nav><section class="settings-panel"><h3>Identidade do escritório</h3><p>Personalize a experiência que a equipe e seus clientes encontram.</p><div class="field" style="max-width:440px;margin-bottom:15px"><label>Nome exibido</label><input value="Estúdio Alpendre" /></div><div class="field" style="max-width:440px;margin-bottom:15px"><label>Assinatura de marca</label><input value="Arquitetura com espaço para crescer" /></div><div class="setting-row"><div><b>Logo do escritório</b><small>Prévia da marca aplicada ao ambiente</small></div><img src="/assets/alpendre-logo.png" alt="Logo Alpendre Gestão" style="width:125px;height:45px;object-fit:contain" /></div><div class="setting-row"><div><b>Paleta de cores</b><small>Base visual exclusiva para a demonstração Alpendre</small></div><span style="display:flex;gap:5px"><i style="width:19px;height:19px;border-radius:6px;background:#35143f"></i><i style="width:19px;height:19px;border-radius:6px;background:#eb5576"></i><i style="width:19px;height:19px;border-radius:6px;background:#c9dd3b"></i><i style="width:19px;height:19px;border-radius:6px;background:#f5f2f6;border:1px solid #ddd"></i></span></div><div class="setting-row"><div><b>Domínio próprio</b><small>Conexão via DNS e TLS com validação de propriedade</small></div><span class="status neutral">Integração preparada</span></div><div class="setting-row"><div><b>Portal do cliente</b><small>Visualização limitada por projeto e convite com prazo</small></div><button class="toggle on" data-toggle aria-label="Ativar portal"></button></div><div class="setting-row"><div><b>Marca Alpendre na área do cliente</b><small>Modo white label permite personalizar nome e identidade</small></div><button class="toggle on" data-toggle aria-label="Ativar white label"></button></div><div class="setting-row"><div><b>Notas fiscais e assinatura digital</b><small>Conectores prontos para ativação com credenciais da organização</small></div><span class="status warn">Aguardando integração</span></div></section></div><div class="demo-note">A configuração visual é uma simulação. Domínio, e-mail, assinatura digital e cobrança exigem chaves e contas próprias configuradas por ambiente.</div>`}
function platformView(mod){return `<section class="page-head"><div><h1>Central SaaS</h1><p>Operação multiempresa, onboarding, planos e saúde da plataforma.</p></div><div class="head-actions"><span class="demo-pill"><i></i> Operador de demonstração</span><button class="btn btn-primary btn-small" data-action="quick-create">${icon('plus')} Novo escritório</button></div></section><div class="metric-grid">${metric('Escritórios ativos','24','+4| no mês','client')}${metric('Usuários convidados','138','+12%| no trimestre','team')}${metric('Ativação média','78%','+9,4%| em 30 dias','chart')}${metric('Integrações prontas','06','+2| neste ciclo','automation')}</div><section class="panel-grid"><article class="panel"><header class="panel-title"><div><h3>Escritórios na plataforma</h3><p>Ambientes e estado de ativação</p></div><button class="link-button" data-action="filter">Ver saúde</button></header><div class="project-list">${[['Estúdio Alpendre','Essencial · 4 usuários · ativo','Ativo',63],['Traço Norte Arquitetura','Equipe · 8 usuários · onboarding','Configuração',48],['Casa Clara Interiores','Essencial · 3 usuários · ativo','Ativo',81],['Linha de Dentro Studio','Equipe · 11 usuários · pagamento','Atenção',54]].map((p,i)=>`<div class="project-row"><span class="workspace-icon">${icon('client')}</span><span class="project-info"><strong>${p[0]}</strong><small>${p[1]}</small><span class="progress"><i style="width:${p[3]}%;background:${i===3?'#e5a856':''}"></i></span></span><span class="status ${i===3?'warn':''}">${p[2]}</span></div>`).join('')}</div></article><article class="panel"><header class="panel-title"><div><h3>Integrações e provedores</h3><p>Conectores preparados por ambiente</p></div></header>${[['Cloudflare D1','Banco e API de dados','Em preparação'],['Cloudflare R2','Arquivos privados e versões','Preparado'],['Assinatura eletrônica','Clicksign / DocuSign','Aguardando credenciais'],['Pagamentos SaaS','Asaas / Stripe','Aguardando credenciais'],['E-mail transacional','Resend / SMTP','Aguardando domínio']].map(x=>`<div class="detail-row"><span>${x[0]}<br><small>${x[1]}</small></span><b><span class="status neutral">${x[2]}</span></b></div>`).join('')}</article></section><section class="panel"><header class="panel-title"><div><h3>Checklist de ativação do tenant</h3><p>Fluxo de onboarding com etapas rastreáveis</p></div><span class="status">6 etapas</span></header><div class="module-toolbar">${['Criar organização','Identidade e domínio','Convidar equipe','Importar dados','Conectar integrações','Treinamento inicial'].map((x,i)=>`<span class="filter-chip">${i<3?'✓':'○'} ${x}</span>`).join('')}</div></section><div class="demo-note">Escritórios, usuários, consumo e planos são fictícios. Cobrança, autenticação multiempresa e conectores externos requerem configuração de produção.</div>`}
function openCreate(id){const mod=moduleBy(id);if(!mod)return;document.getElementById('overlay-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">Novo registro</h2><p>Preencha os dados demonstrativos de ${escapeHtml(mod.label.toLowerCase())}.</p></div><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button></header><form class="modal-body" id="record-form" data-module="${id}"><div class="form-grid"><div class="field full"><label for="record-name">Nome do registro</label><input id="record-name" required maxlength="100" placeholder="Ex.: Residência Mangabeira" /></div><div class="field"><label for="record-sub">Categoria ou vínculo</label><input id="record-sub" maxlength="80" placeholder="Ex.: Residencial · João Pessoa" /></div><div class="field"><label for="record-status">Etapa</label><select id="record-status"><option>Em andamento</option><option>Novo</option><option>Aguardando</option><option>Concluído</option><option>Em revisão</option></select></div><div class="field full"><label for="record-desc">Resumo e próximo passo</label><textarea id="record-desc" maxlength="240" placeholder="Descreva o próximo passo deste registro"></textarea></div></div><div class="modal-actions"><button type="button" class="btn btn-outline btn-small" data-action="close-modal">Cancelar</button><button class="btn btn-primary btn-small" type="submit">Salvar registro</button></div></form></section></div>`}
function detailDrawer(id,index){const mod=moduleBy(id);const row=listItems(id)[index];if(!mod||!row)return;document.getElementById('overlay-root').innerHTML=`<div class="drawer-wrap" data-action="drawer-backdrop"><aside class="drawer" role="dialog" aria-modal="true"><div class="drawer-top"><span>${escapeHtml(mod.label)} · Registro demonstrativo</span><button class="modal-close" data-action="close-drawer" aria-label="Fechar">×</button></div><span class="status ${statusClass(row.status)}">${escapeHtml(row.status)}</span><h2 class="drawer-title">${escapeHtml(row.name)}</h2><p class="drawer-sub">${escapeHtml(row.subtitle)}</p><div class="detail-layout"><div class="detail-main"><section class="detail-box"><h3>Resumo</h3><p>${escapeHtml(row.description)}. Este painel organiza o histórico e o próximo passo deste registro dentro do escritório.</p><div class="detail-row"><span>Responsável</span><b>${['Helena Nogueira','Lívia Carvalho','Caio Medeiros'][index%3]}</b></div><div class="detail-row"><span>Atualizado em</span><b>21 nov 2026, ${String(9+index).padStart(2,'0')}:30</b></div><div class="detail-row"><span>${['financeiro','crm','propostas'].includes(id)?'Valor demonstrativo':'Referência'}</span><b>${escapeHtml(row.value)}</b></div></section><section class="detail-box"><h3>Histórico e próximos passos</h3><div class="timeline"><div class="timeline-item"><span class="timeline-mark">✓</span><span><b>Registro criado no ambiente</b><small>Dados demonstrativos · 18 nov 2026</small></span></div><div class="timeline-item"><span class="timeline-mark">↗</span><span><b>${escapeHtml(row.description)}</b><small>Helena Nogueira · 21 nov 2026</small></span></div><div class="timeline-item"><span class="timeline-mark">○</span><span><b>Próxima ação: revisar e atualizar etapa</b><small>Prazo estimado · 24 nov 2026</small></span></div></div></section></div><div class="detail-aside"><section class="detail-box"><h3>Ações rápidas</h3><button class="btn btn-outline btn-small" style="width:100%;margin-bottom:7px" data-action="record-action">Registrar atividade</button><button class="btn btn-outline btn-small" style="width:100%;margin-bottom:7px" data-action="record-action">Criar tarefa vinculada</button><button class="btn btn-outline btn-small" style="width:100%" data-action="record-action">Compartilhar com cliente</button></section><section class="detail-box"><h3>Integridade do registro</h3><p>Visibilidade limitada ao espaço de demonstração. Dados fictícios; nenhuma informação de cliente real.</p><div class="detail-row"><span>Organização</span><b>Estúdio Alpendre</b></div><div class="detail-row"><span>Atividade registrada</span><b>Simulada</b></div></section></div></div></aside></div>`}
function toast(msg){const wrap=document.getElementById('toast-wrap');if(!wrap)return;wrap.innerHTML=`<div class="toast"><span>✓</span>${escapeHtml(msg)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{if(wrap)wrap.innerHTML=''},3000)}
function render(){const hash=location.hash.replace('#','');if(hash==='gestao'||hash.startsWith('gestao/')){const mod=hash.split('/')[1];if(mod&&moduleBy(mod))current=mod;root.innerHTML=appShell();if(!apiCheckStarted)syncDemoApi();}else{root.innerHTML=landing();}bind()}
async function syncDemoApi(){apiCheckStarted=true;const pill=document.getElementById('api-status');try{const response=await fetch(`${window.ALPN_API_BASE}/api/demo/summary`,{headers:{accept:'application/json'}});if(!response.ok)throw new Error('API indisponível');const data=await response.json();const count=(data.records||[]).reduce((sum,row)=>sum+Number(row.count||0),0);if(pill)pill.innerHTML=`<i></i> Cloudflare D1 conectado · ${count} amostras`; }catch{if(pill)pill.innerHTML='<i></i> Demonstração local · integração preparada';} }
function bind(){root.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',()=>{const id=el.dataset.nav;current=id;location.hash=`gestao/${id}`;document.getElementById('sidebar')?.classList.remove('open');document.querySelector('.mobile-overlay')?.classList.remove('show')}));root.querySelectorAll('[data-action="demo"]').forEach(el=>el.addEventListener('click',()=>{current='overview';location.hash='gestao'}));root.querySelectorAll('[data-action="menu"]').forEach(el=>el.addEventListener('click',()=>{document.getElementById('sidebar')?.classList.add('open');document.querySelector('.mobile-overlay')?.classList.add('show')}));root.querySelectorAll('[data-action="close-menu"]').forEach(el=>el.addEventListener('click',()=>{document.getElementById('sidebar')?.classList.remove('open');el.classList.remove('show')}));root.querySelectorAll('[data-create]').forEach(el=>el.addEventListener('click',()=>openCreate(el.dataset.create)));root.querySelectorAll('[data-detail]').forEach(el=>el.addEventListener('click',()=>detailDrawer(el.dataset.detail,Number(el.dataset.row))));root.querySelectorAll('[data-task]').forEach(el=>el.addEventListener('click',()=>{const i=Number(el.dataset.task);state.doneTasks=state.doneTasks.includes(i)?state.doneTasks.filter(x=>x!==i):[...state.doneTasks,i];setState();render()}));root.querySelectorAll('[data-toggle]').forEach(el=>el.addEventListener('click',()=>{el.classList.toggle('on');toast(el.classList.contains('on')?'Preferência ativada para a demonstração':'Preferência desativada para a demonstração')}));root.querySelectorAll('[data-action="close-modal"],[data-action="close-drawer"]').forEach(el=>el.addEventListener('click',()=>document.getElementById('overlay-root').innerHTML=''));root.querySelectorAll('[data-action="backdrop"],[data-action="drawer-backdrop"]').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)document.getElementById('overlay-root').innerHTML=''}));root.querySelectorAll('[data-action="quick-create"]').forEach(el=>el.addEventListener('click',()=>openCreate('crm')));root.querySelectorAll('[data-action="notifications"]').forEach(el=>el.addEventListener('click',()=>toast('Você está em dia com as notificações demonstrativas.')));root.querySelectorAll('[data-action="save-settings"]').forEach(el=>el.addEventListener('click',()=>toast('Preferências salvas neste navegador.')));root.querySelectorAll('[data-action="settings-tab"]').forEach(el=>el.addEventListener('click',()=>{root.querySelectorAll('[data-action="settings-tab"]').forEach(x=>x.classList.remove('active'));el.classList.add('active');toast(`${el.textContent} · área demonstrativa`)}));root.querySelectorAll('[data-action="filter"],[data-action="switch-view"]').forEach(el=>el.addEventListener('click',()=>toast('Filtro aplicado ao conjunto demonstrativo.')));root.querySelectorAll('[data-action="export"]').forEach(el=>el.addEventListener('click',()=>exportRows(el.dataset.module)));const search=document.getElementById('global-search');if(search)search.addEventListener('input',()=>{globalFilter=search.value;const mainSearch=document.getElementById('module-filter');if(mainSearch){mainSearch.value=globalFilter;mainSearch.dispatchEvent(new Event('input'))}else if(globalFilter.length>1){const match=sampleModules.find(m=>m.items.some(row=>row.join(' ').toLowerCase().includes(globalFilter.toLowerCase())));if(match)toast(`Há resultados em ${match.label}. Abra o módulo para refinar.`)}});const filter=document.getElementById('module-filter');if(filter)filter.addEventListener('input',()=>{globalFilter=filter.value;const cursor=filter.selectionStart;const id=current;const query=globalFilter;const view=document.querySelector('.content');if(view){const page=moduleView(id);view.innerHTML=page;bind();const next=document.getElementById('module-filter');next?.focus();next?.setSelectionRange(cursor,cursor)}});const form=document.getElementById('record-form');if(form)form.addEventListener('submit',e=>{e.preventDefault();const id=form.dataset.module;const name=document.getElementById('record-name').value.trim();if(!name)return;const rec={id:`${id}-demo-${Date.now()}`,name,subtitle:document.getElementById('record-sub').value.trim()||'Registro demonstrativo · Escritório Alpendre',description:document.getElementById('record-desc').value.trim()||'Próximo passo definido para acompanhamento',status:document.getElementById('record-status').value,value:'Demonstração',created:new Date().toISOString()};state.extra[id]=[rec,...(state.extra[id]||[])];setState();document.getElementById('overlay-root').innerHTML='';render();toast('Registro salvo neste navegador de demonstração.')});root.querySelectorAll('[data-action="record-action"]').forEach(el=>el.addEventListener('click',()=>toast('Ação registrada no fluxo demonstrativo.')))}
function exportRows(id){const mod=moduleBy(id);const rows=listItems(id);const csv=[['Registro','Categoria','Resumo','Etapa','Valor demonstrativo'],...rows.map(r=>[r.name,r.subtitle,r.description,r.status,r.value])].map(row=>row.map(x=>'"'+String(x||'').replaceAll('"','""')+'"').join(';')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`alpendre-demo-${id}.csv`;a.click();URL.revokeObjectURL(a.href);toast(`Exportação de ${mod.label} preparada.`)}
window.addEventListener('hashchange',render);render();
